import pandas as pd


def run(inputs: dict) -> dict:
    target_snapshot = inputs["target_snapshot"]
    cdc_events = inputs["cdc_events"]
    watermark = inputs["watermark"]

    # Determine watermark high_ts (assume single relevant value; use max if multiple rows)
    if len(watermark) > 0:
        high_ts = watermark["high_ts"].max()
    else:
        high_ts = pd.NaT

    # Initialize state from target_snapshot
    state = {}
    for row in target_snapshot.itertuples(index=False):
        state[row.item_id] = {
            "exists": True,
            "qty": float(row.qty_on_hand),
            "last_ts": row.last_event_ts,
        }

    # Filter events not yet applied (event_ts > high_ts)
    if pd.isna(high_ts):
        events_to_apply = cdc_events.copy()
    else:
        events_to_apply = cdc_events[cdc_events["event_ts"] > high_ts].copy()

    # Sort events by item_id, then (event_ts, event_seq) to apply sequentially per item
    events_to_apply = events_to_apply.sort_values(
        by=["item_id", "event_ts", "event_seq"], kind="mergesort"
    )

    for row in events_to_apply.itertuples(index=False):
        item_id = row.item_id
        op = row.op
        qty = row.qty
        ts = row.event_ts

        if item_id not in state:
            state[item_id] = {"exists": False, "qty": 0.0, "last_ts": None}

        entry = state[item_id]

        if op == "R":
            if not entry["exists"]:
                entry["qty"] = 0.0
            entry["qty"] = entry["qty"] + float(qty)
            entry["exists"] = True
            entry["last_ts"] = ts
        elif op == "A":
            entry["qty"] = float(qty)
            entry["exists"] = True
            entry["last_ts"] = ts
        elif op == "D":
            entry["exists"] = False
            entry["last_ts"] = ts
        # unknown ops ignored

    # Build output: only items that currently exist
    out_rows = []
    for item_id, entry in state.items():
        if entry["exists"]:
            out_rows.append(
                {
                    "item_id": item_id,
                    "qty_on_hand": entry["qty"],
                    "last_event_ts": entry["last_ts"],
                }
            )

    if out_rows:
        new_snapshot = pd.DataFrame(out_rows, columns=["item_id", "qty_on_hand", "last_event_ts"])
    else:
        new_snapshot = pd.DataFrame(columns=["item_id", "qty_on_hand", "last_event_ts"])

    new_snapshot["item_id"] = new_snapshot["item_id"].astype("int64")
    new_snapshot["qty_on_hand"] = new_snapshot["qty_on_hand"].astype("float64")
    new_snapshot["last_event_ts"] = pd.to_datetime(new_snapshot["last_event_ts"])

    new_snapshot = new_snapshot.sort_values(by="item_id", kind="mergesort").reset_index(drop=True)

    return {"new_snapshot": new_snapshot}
